#!/bin/bash
# Запуск на сервере: bash install-nginx-lesson.sh
set -euo pipefail
base64 -d >/etc/nginx/sites-available/lesson.itflux-academy.ru <<'B64'

B64
ln -sfn /etc/nginx/sites-available/lesson.itflux-academy.ru /etc/nginx/sites-enabled/lesson.itflux-academy.ru
nginx -t
systemctl reload nginx
echo OK
curl -sk -D- -o /tmp/cws -m 5 -H 'Host: lesson.itflux-academy.ru' https://127.0.0.1/colibri-ws/default-id/test | head -12
echo BODY:; head -c 80 /tmp/cws; echo
file /tmp/cws
